/* ============================================================
   MODULES · ORDERFLOW, the precursor to the strategies. Ten modules: what orderflow is, the tape and the DOM, the footprint, delta, imbalances,
   absorption and exhaustion, auction theory, then orderflow at sweeps (ECHO and ORBIT), at gaps and levels (INVERTIX), and a checklist that puts it all beside the strategies.
   Concepts and rules only: no results, win rates or statistics. Orderflow is context and confirmation, never a trigger on its own.
   Every module has an exam (80% to pass). Passing all ten opens INVERTIX, ECHO and ORBIT.
============================================================ */
(()=>{
const ri=(r,a,b)=>a+Math.floor(r()*(b-a+1));
/* a footprint ladder: rows are [price, sellers hitting the bid, buyers lifting the ask], highest price first */
const fpRows=(rows,o={})=>rows.map(([p,b,a],i)=>`<tr style="animation:lcIn .45s ease both;animation-delay:${i*.07}s"><td><b>${fm(p,0)}</b></td><td class="${o.b&&o.b.includes(i)?'imb':''}">${b}</td><td class="${o.a&&o.a.includes(i)?'imb':''}">${a}</td></tr>`).join('');
const fp=(rows,o={})=>`<table class="tblx fp"><tr><th>Price</th><th>Sellers (hit the bid)</th><th>Buyers (lift the ask)</th></tr>${fpRows(rows,o)}</table>`;
const fpHead='<tr><th>Price</th><th>Sellers (bid)</th><th>Buyers (ask)</th></tr>';
const sum=(rows,k)=>rows.reduce((a,x)=>a+x[k],0);
const base=r=>pick(r,[20150,21400,24380,27610]);
/* ---------- generators ---------- */
const deltaCalc=numGen('Delta',r=>{const p=base(r),n=ri(r,4,5),rows=Array.from({length:n},(_,i)=>[p+(n-1-i),ri(r,12,95),ri(r,12,95)]),b=sum(rows,1),a=sum(rows,2);
  return{q:'This candle traded the volumes below. Delta is the buyers (at the ask) minus the sellers (at the bid). What is the candle\'s delta? Use a minus sign if sellers won.',table:fpHead+fpRows(rows),ans:a-b,unit:'contracts',tol:.01,why:`Buyers ${a} minus sellers ${b} = ${a-b}. ${a>b?'More traded at the ask: buyers were the aggressors.':a<b?'More traded at the bid: sellers were the aggressors.':'Even: neither side was more aggressive.'}`}});
const totalVol=numGen('Volume',r=>{const p=base(r),n=ri(r,4,5),rows=Array.from({length:n},(_,i)=>[p+(n-1-i),ri(r,10,80),ri(r,10,80)]),t=sum(rows,1)+sum(rows,2);
  return{q:'Add up every cell in this candle. How many contracts traded in total (the candle\'s volume)?',table:fpHead+fpRows(rows),ans:t,unit:'contracts',tol:.01,why:`Sellers ${sum(rows,1)} + buyers ${sum(rows,2)} = ${t}. Volume is every contract that traded, on both sides. Delta is only the difference.`}});
const cumDelta=numGen('Cumulative delta',r=>{const d=Array.from({length:5},()=>ri(r,-140,160)),t=d.reduce((a,x)=>a+x,0);
  return{q:`Five candles in a row print these deltas: ${d.map(x=>(x>0?'+':'')+x).join(', ')}. What is the cumulative delta at the end of the fifth candle (starting from zero)?`,ans:t,unit:'',tol:.01,why:`Cumulative delta is the running total of delta: ${d.map(x=>(x>0?'+':'')+x).join(' ')} = ${t>0?'+':''}${t}.`}});
const diagImb=numGen('Imbalances',r=>{const p=base(r),n=5,rows=[],ix=ri(r,1,3);
  for(let i=0;i<n;i++)rows.push([p+(n-1-i),ri(r,15,45),ri(r,15,45)]);
  /* the row above the target (higher price) has the ask volume; compare it with the bid one row below. Make exactly one buy imbalance (ask at least 3 times the bid one row down). */
  for(let i=0;i<n-1;i++){const askHere=rows[i][2],bidBelow=rows[i+1][1];if(askHere>=3*bidBelow)rows[i][2]=Math.min(askHere,3*bidBelow-1)}
  const t=ix;rows[t][2]=3*rows[t+1][1]+ri(r,4,15);
  return{q:'A buy imbalance means the ask volume at a price is at least 3 times the bid volume one row below it (a diagonal comparison). Only one price here has a buy imbalance. At which price is it?',table:fpHead+fpRows(rows),ans:rows[t][0],unit:'',tol:.01,why:`At ${fm(rows[t][0],0)} the ask is ${rows[t][2]} and the bid one row below (${fm(rows[t+1][0],0)}) is ${rows[t+1][1]}. ${rows[t][2]} is at least 3 × ${rows[t+1][1]} = ${3*rows[t+1][1]}, so buyers were far more aggressive there. No other row passes the 3 × test.`}});
const stackCount=numGen('Stacked imbalances',r=>{const p=base(r),k=ri(r,2,5),len=7,start=ri(r,0,len-k),rows=Array.from({length:len},(_,i)=>[p+(len-1-i),ri(r,12,30),ri(r,12,30)]);
  for(let i=0;i<len-1;i++)rows[i][2]=Math.min(rows[i][2],3*rows[i+1][1]-1);
  for(let i=start;i<start+k&&i<len-1;i++)rows[i][2]=3*rows[i+1][1]+ri(r,3,12);
  const run=(()=>{let best=0,cur=0;for(let i=0;i<len-1;i++){if(rows[i][2]>=3*rows[i+1][1]){cur++;best=Math.max(best,cur)}else cur=0}return best})();
  return{q:'Each ask here is compared with the bid one row below it. How many buy imbalances in a row (the biggest stack) does this candle show? A stack is three or more, but give the count you see.',table:fpHead+fpRows(rows),ans:run,unit:'in a row',tol:.01,why:`Compare each ask with 3 × the bid one row down. The longest unbroken run of buy imbalances here is ${run}. ${run>=3?'That is a stacked imbalance: buyers were aggressive across several prices in a row.':'Fewer than three in a row is not a stack.'}`}});
const pocQ=numGen('Point of control',r=>{const p=base(r),n=7,vols=Array.from({length:n},()=>ri(r,40,160)),m=ri(r,2,4);vols[m]=Math.max(...vols)+ri(r,12,40);
  const rows=vols.map((v,i)=>`<tr style="animation:lcIn .45s ease both;animation-delay:${i*.07}s"><td><b>${fm(p+n-1-i,0)}</b></td><td colspan="2"><span class="vbar" style="display:inline-block;height:10px;border-radius:3px;background:var(--ice);width:${v/2.2}px"></span> ${v}</td></tr>`).join('');
  return{q:'This is a volume profile: the contracts traded at each price over the session. Where is the point of control (the price with the most volume)?',table:'<tr><th>Price</th><th colspan="2">Volume at that price</th></tr>'+rows,ans:p+n-1-m,unit:'',tol:.01,why:`The longest bar is ${vols[m]} contracts at ${fm(p+n-1-m,0)}. That price is the point of control: where the most business was done, and often the price the market treats as fair.`}});
const ammoQ=numGen('Passive orders',r=>{const L=pick(r,[40,60,85,120]),B=ri(r,12,L-6),px=base(r);
  return{q:`${L} contracts are resting to sell at ${fm(px,2)} (passive sell orders on the ask). A buyer sends a market order for ${B} contracts. How many contracts are still resting there afterwards?`,ans:L-B,unit:'contracts',tol:.01,why:`${L} resting − ${B} bought = ${L-B}. A market order takes what is resting: it is the aggressive side, the resting orders are the passive side.`}});
const spreadQ=numGen('The spread',r=>{const px=base(r),sp=pick(r,[1,2,3]),tick=.25,bid=px+.5,ask=bid+sp*tick,cost=sp*tick*20;
  return{q:`The best bid is ${fm(bid,2)} and the best ask is ${fm(ask,2)} on NQ ($20 a point, tick 0.25). A market buy followed straight away by a market sell fills at the ask and then the bid. How many dollars does that round trip cost per NQ contract (before commissions)?`,ans:cost,unit:'$',tol:.01,why:`The spread is ${fm(sp*tick,2)} points × $20 = $${fm(cost,2)}. The market order that crosses the spread pays it. A limit order that waits does not.`}});
const aggressorQ=r=>{const k=pick(r,[
 ['A market buy order is sent.','It takes the best ask: the buyer is the aggressor and the resting sellers are passive','It joins the bid and waits: the buyer is passive','It cancels resting orders','It moves the bid down'],
 ['A market sell order is sent.','It hits the best bid: the seller is the aggressor and the resting buyers are passive','It joins the ask and waits','It lifts the ask','It adds to the bid'],
 ['A buy limit order is placed below the market.','It rests on the bid and waits: it is passive until a seller hits it','It fills straight away','It is the aggressor','It pushes the ask up']]);
  return mcq('Aggressive and passive',k[0]+' What happens?',[k[1],k[2],k[3],k[4]],'Market orders are aggressive: they take the price on the other side right now. Limit orders are passive: they rest and wait to be hit.')};
const printQ=r=>{const k=pick(r,[
 ['A trade prints at the ask price.','A buyer lifted the offer: buying was the aggressive side','A seller hit the bid','The trade was cancelled','It is a limit order resting'],
 ['A trade prints at the bid price.','A seller hit the bid: selling was the aggressive side','A buyer lifted the offer','It is not a real trade','The price is about to rise'],
 ['A very large print appears on the tape.','Note it as context: it is large compared with normal size, but it alone does not say direction','Always follow it','Always fade it','Ignore the tape']]);
  return mcq('Reading the tape',k[0]+' What does it tell you?',[k[1],k[2],k[3],k[4]],'The tape shows each trade and which side it traded on. The price side tells you who was aggressive. Size is context, not a signal on its own.')};
const domQ=r=>{const k=pick(r,[
 ['A big sell order sits on the ask on the DOM and then vanishes before price reaches it.','Resting orders can be pulled at any time: do not trade off the DOM alone','Buyers won','It is proof of a big seller','The market is closed'],
 ['The DOM shows a large buy order just under the market.','It may be real support or it may be pulled: it is only one clue and only counts if trades actually happen into it','Price must bounce','Price must break','You must buy at once'],
 ['Only a small slice of an order shows on the DOM and it keeps refilling as it is hit.','It can be a large order hidden in small pieces (an iceberg): watch whether price can pass it','It is a data error','The exchange is closed','It is a stop order']]);
  return mcq('The DOM',k[0]+' What is the right read?',[k[1],k[2],k[3],k[4]],'The DOM shows resting orders, which can be pulled or hidden. What actually traded (the tape and footprint) is real. Use the DOM as a clue, never as a promise.')};
const absorbQ=r=>{const k=pick(r,[
 ['Price runs into a level on heavy volume, buyers hit the ask again and again, and price barely moves.','Absorption: a big passive seller is soaking up the buying','A breakout, buy more','A gap','A news spike'],
 ['Price makes a high on weak, fading volume after a long run up and the last candle has little delta.','Exhaustion: the push has run out of aggression','Absorption of sellers','A new trend starting','A stop run'],
 ['Buyers who bought the break are now underwater as price falls back through the level.','Trapped traders: their stops add to the move down','Absorption','An iceberg','A gap fill'],
 ['A candle closes up but its delta is negative.','The close and the aggression disagree: a warning, not a signal on its own','A strong bullish candle','A normal candle','A data error']]);
  return mcq('Absorption and exhaustion',k[0]+' What is it?',[k[1],k[2],k[3],k[4]],'Absorption: lots of aggressive volume, little progress. Exhaustion: the push runs out of fuel. Trapped traders: late entries forced to exit against the move.')};
const sortAbs=r=>{const A=['Heavy volume at a level, price will not go through','A wick on big volume with little delta change','Sellers keep hitting the bid and price will not fall'],E=['The push up fades: smaller delta on each new high','Volume dries up as price grinds to a new high','The last candle of a run has tiny delta'],T=['Buyers who bought the break are stopped out as price falls back','Late sellers are squeezed as price snaps back up','A failed breakout forces the break traders to exit'];
  const a=pickN(r,A,2),e=pickN(r,E,2),t=pickN(r,T,2);return{kind:'sort',topic:'Absorption and exhaustion',q:'Sort each description under the name it fits.',buckets:['Absorption','Exhaustion','Trapped traders'],items:shuf([...a.map(x=>({t:x,b:0})),...e.map(x=>({t:x,b:1})),...t.map(x=>({t:x,b:2}))],r),why:'Absorption is a passive side soaking up aggression. Exhaustion is a push running out of fuel. Trapped traders are late entries forced out when a break fails.'}};
const divQ=r=>{const k=pick(r,[
 ['Price makes a higher high but cumulative delta makes a lower high.','Bearish delta divergence: the new high had less aggression behind it. A condition to watch, not a trigger','A sure reversal down','A buy signal','Nothing at all'],
 ['Price makes a lower low but cumulative delta makes a higher low.','Bullish delta divergence: the new low had less selling behind it. A condition to watch, not a trigger','A sure reversal up','A sell signal','A data error'],
 ['Price makes a higher high and cumulative delta makes a higher high too.','They agree: aggression is behind the move','A divergence','A reason to short at once','A news event']]);
  return mcq('Delta divergence',k[0]+' What is it?',[k[1],k[2],k[3],k[4]],'Divergence means price and aggression disagree. It can repeat many times while a trend keeps going, so it is a reason to look closer, never a trade by itself.')};
const shapeQ=r=>{const k=pick(r,[
 ['A profile is fat at the top and has a thin tail running down.','P shape: often buyers moved price up and it was then accepted high','D shape: a balanced day','b shape: sellers moved price down and it settled low','Thin and long: a fast trend'],
 ['A profile is fat at the bottom with a thin tail running up.','b shape: often a sell-off that was then accepted low','D shape: a balanced day','P shape: a buying push that settled high','Thin and long: a fast trend'],
 ['A profile is a neat bell around one price.','D shape: a balanced day, price rotated around one fair price','P shape: buyers took over','b shape: sellers took over','Thin and long: a fast trend'],
 ['A profile is long, thin and even, with no price where much traded.','Thin and long: a fast move that accepted little','D shape: a balanced day','P shape: a buying push that settled high','b shape: a sell-off that settled low']]);
  return mcq('Profile shapes',k[0]+' What is it?',[k[1],k[2],k[3],k[4]],'D is a bell (balance). P has volume high, b has volume low. A thin, even profile is a fast move that accepted little. These describe the day, they do not forecast the next candle.')};
const nodeQ=r=>{const k=pick(r,[
 ['Price is moving through a range where the profile shows very little volume.','A low volume node: price ran through it fast, like a fair value gap','A high volume node','The point of control','The value area'],
 ['The profile has a long, tall bar at one price.','A high volume node (and likely the POC): the market accepted that price','A low volume node','A fair value gap','A news spike'],
 ['Price approaches a high volume node.','It often slows down or rotates there: it is a price the market accepted','It must break through','It must gap','It will not trade there'],
 ['Which profile feature matches a fair value gap on a candle chart?','A low volume node','The point of control','A high volume node','The value area high']]);
  return mcq('Volume nodes',k[0]+' What is it?',[k[1],k[2],k[3],k[4]],'A high volume node is accepted price. A low volume node is a skipped range, the profile version of a fair value gap.')};
const stackRole=r=>{const k=pick(r,[
 ['Stacked buy imbalances show up on a candle that breaks up out of a range.','Often continuation: aggressive buying across several prices. Do not fade it without more','Always a reversal sign','A sell signal','Meaningless'],
 ['Stacked buy imbalances appear on the way down into a level and price then holds above them.','The stack can act as support: buyers showed up there','It always breaks','A sell signal','Nothing'],
 ['A single imbalance cell appears alone on a quiet candle.','One cell is weak: stacks of three or more carry more weight','A strong signal','A reversal','A gap']]);
  return mcq('Stacked imbalances',k[0]+' How do you read it?',[k[1],k[2],k[3],k[4]],'A single imbalance is noise. A stack of three or more in a row is a footprint of aggression across prices, and it often continues. As a zone it can also act as support or resistance.')};
const auctionQ=r=>{const k=pick(r,[
 ['Price opens below yesterday\'s value area and starts to move down away from it.','Initiative selling: moving away from value looking for new value','Responsive buying','Balance','A gap fill'],
 ['Price pokes above yesterday\'s high, then is sold and falls back inside yesterday\'s range.','Responsive selling: buyers failed to find acceptance above value','Initiative buying','A confirmed breakout','Balance forever'],
 ['Price rotates in a tight range around the point of control all morning.','Balance: both sides agree on value for now','Strong trend','Exhaustion','Absorption of everyone'],
 ['Price leaves the value area and holds outside it with rising volume.','Imbalance: the market is looking for a new value area','Balance','Absorption','Nothing'],
 ['A high is made with a single print and no trading above it.','Excess: price was rejected hard, a sign the auction has finished there','A buy signal','Value','A gap']]);
  return mcq('Auction theory',k[0]+' What is it?',[k[1],k[2],k[3],k[4]],'Auction theory: the market is a two-way auction looking for fair value. Moving away from value is initiative, returning toward it is responsive, and acceptance or rejection tells you which one is winning.')};
const confirmQ=r=>{const k=pick(r,[
 ['Price sweeps a high and closes back below it, and the footprint on that candle shows heavy aggressive buying that made no progress.','Good context: the sweep was absorbed. Still wait for the strategy\'s own signal','Enter short at once','Enter long','Skip the day'],
 ['Price sweeps a low, but the footprint shows sellers still hitting the bid hard and price keeps falling.','Flow does not back the rejection: the strategy\'s signal is not there yet, so skip','Buy because it is a sweep','Move your stop','Double size'],
 ['The strategy signal prints but the footprint is thin and unclear.','Unclear flow is not a reason to break your rules: the strategy still decides, flow only adds or removes confidence','Skip every signal','Double size','Move the stop'],
 ['The strategy signal prints and flow disagrees strongly.','A reason to skip or take less risk: flow is your second opinion','Ignore it and add size','Move your stop wider','Hold forever']]);
  return mcq('Flow and the signal',k[0]+' What do you do?',[k[1],k[2],k[3],k[4]],'The strategy gives the trigger. Orderflow is a second opinion: it can add confidence or tell you to skip, but it never replaces the strategy\'s rules, the windows, the stop or the size.')};
const sweepOrder=()=>({kind:'order',topic:'Sweeps',q:'Put the orderflow story of a stop run and rejection in order.',steps:['Price moves toward a level where stops are resting','Price trades through the level and aggressive orders flood in as the stops fire','The aggression stops making progress: price cannot hold beyond the level (absorption)','Price closes back inside the level: the sweep is rejected','Only now does the strategy look for its own confirmation, such as the CISD or an inversion'],why:'Run toward the level, stops fire, aggression stalls, price closes back, then the strategy\'s own confirmation. The flow tells the story, the strategy gives the trigger.'});
const fitQ=r=>{const k=pick(r,[
 ['ECHO','Price sweeps a high, then a rejection block forms and price closes back through the CISD line','Aggression into the sweep that stalls, then delta flipping against the sweep','Aggression that keeps winning after the sweep, with price holding beyond the level'],
 ['ORBIT','Price retraces into the 3-minute optimal entry zone and a 5-minute inversion confirms','A pullback into the zone on light, fading aggression, then a move away on stronger delta','A heavy, one-sided pullback straight through the zone against you'],
 ['INVERTIX','Price runs into a key level, then closes through the highest small gap in the leg (the flip)','A leg into the key level that runs out of aggression, then a flip candle with strong delta the other way','A weak flip candle while the leg\'s aggression is still strong']]);
  return mcq('Flow beside each strategy',`In ${k[0]}: ${k[1]}. Which of these is orderflow that BACKS the setup?`,[k[2],k[3],'Flow that replaces the strategy\'s signal','Flow that lets you ignore the stop'],'In every strategy, flow is a second opinion beside the rules: it can add confidence or tell you to skip. The rules, the windows, the stop and the size do not change.')};
const fvgRbQ=r=>{const k=pick(r,[
 ['What does a fair value gap look like in orderflow terms?','A range where one side was so aggressive that price skipped through it: stacked imbalances and thin rows','A range with the most volume','A long wick with heavy trading','The value area'],
 ['What does a rejection block look like in orderflow terms?','A wick where heavy aggressive trading was absorbed and price could not stay: heavy volume, little progress, then delta flips','A stack of imbalances with no wick','A gap with no trading','The point of control'],
 ['Price returns to a fair value gap and a candle wicks into it, then closes back out. Which orderflow idea is that?','Absorption: the left-behind orders refuse price, which is the rejection block','Exhaustion of the whole trend','A new gap forming','A finished auction at the high'],
 ['Which is the better way to say the difference between a fair value gap and a rejection block?','The gap is where aggression won, the rejection block is where aggression was refused','The gap is where price is refused, the rejection block is where it ran','They are the same thing','One is for buyers and one is for sellers']]);
  return mcq('FVG and rejection block',k[0],[k[1],k[2],k[3],k[4]],'A fair value gap is aggression winning (imbalance, price skipped). A rejection block is aggression refused (absorption in a wick). ECHO grades the rejection block by the gap it sits in.')};
const neverQ=r=>{const k=pick(r,[
 ['Your stop','Never: the stop stays where the rules put it, whatever the footprint shows'],
 ['The strategy\'s windows','Never: a great-looking footprint outside the window is still outside the window'],
 ['Your position size and daily loss limit','Never: flow cannot make a bigger size safe'],
 ['The strategy\'s own signal','Never: no signal means no trade, however good the flow looks']]);
  return mcq('What flow never overrides',`Can orderflow override ${k[0]}?`,[k[1],'Yes, when flow looks strong','Yes, for the first trade of the day','Yes, if you are in a hurry'],'Orderflow is a second opinion. It never overrides the stop, the windows, the size, the daily limit or the strategy\'s own signal.')};
const lvlQ=r=>{const k=pick(r,[
 ['An unfilled fair value gap is a price range that traded quickly with little business done.','Price is often drawn back to it, and how flow behaves there tells you if it holds','It is always support','It is always resistance','It has no meaning'],
 ['Price reaches a gamma wall (a GEX level) and the footprint shows heavy trading and little progress.','The level is being absorbed: a clue for a reaction, not a promise','A sure bounce','A sure break','The market is closed'],
 ['Price trades into a key level and the push into it comes with smaller and smaller delta.','The push is losing fuel: a reason to watch for the flip','A reason to chase','A reason to double size','Nothing'],
 ['A key level is touched and the footprint is huge and one-sided in the direction of the push.','The level may fail: be patient and wait for the strategy\'s signal','Take the level at once','A sure reversal','Skip the stop']]);
  return mcq('Flow at levels',k[0]+' How do you read it?',[k[1],k[2],k[3],k[4]],'Levels say where to look. Flow says whether the level is being absorbed or run over. The strategy still gives the signal.')};
const gapQ=r=>{const k=pick(r,[
 ['What is a fair value gap in orderflow terms?','A range where price moved so fast that little trading happened','A range with the most volume','A news release','The value area'],
 ['Why does price often return to a fair value gap?','The skipped range left unfinished business: there are resting orders and little earlier trading there','Because gaps are magnets by law','Because of the clock','Because of the spread'],
 ['What is a point of control?','The price with the most volume in the profile','The highest price of the day','The first trade of the day','The widest spread']]);
  return mcq('Gaps and profile',k[0],[k[1],k[2],k[3],k[4]],'A fair value gap is a range price skipped through quickly. The point of control is the opposite: the price where the most business was done.')};
/* ---------- f01 · what orderflow is ---------- */
quick({id:'f01',o:16.1,ph:0,t:'What Orderflow Is',out:'Say what orderflow shows that a candle does not, and tell aggressive orders from passive ones.',
 ls:['A candle shows where, flow shows how','The market is an auction','Aggressive and passive orders','The bid, the ask and the spread','Where orderflow sits beside the strategies'],
 task:'Open any liquid futures chart. Pick one candle and write, in your own words, what it shows you (open, high, low, close) and one thing it cannot show you about how it got there.',
 learn:[
  {t:'A candle shows where, flow shows how',h:`<p>A normal candle tells you <b>where</b> price went: the open, the high, the low and the close. <b>Orderflow</b> shows <b>how</b> it got there: who was pushing, who was soaking it up, and how much traded at each price.</p><p>It does not predict the future. It gives you a second look at the same moment, and you will use it beside the strategies, not instead of them.</p>`+key('<p>Candle: where price went. Orderflow: who made it go there.</p>')+OFV.candleVsFp()},
  {t:'The market is an auction',h:`<p>Every market is an <b>auction</b>. Buyers and sellers meet at a price, trade, and price moves to find the level where both sides will keep trading. Price rises when buyers are willing to pay more and sellers step back. It falls when the reverse is true.</p><p>On NQ and MNQ every trade happens on the CME exchange, so the volume you see is real: every contract that traded is recorded.</p>`},
  {t:'Aggressive and passive orders',h:tblx(['Side','Order','What it does'],[['Aggressive (initiative)','A <b>market order</b>','Takes the best price on the other side right now. It moves price.'],['Passive (responsive)','A <b>limit order</b>','Rests at a price and waits to be hit. It absorbs the aggressor.']])+`<p>Every trade is one aggressive order meeting one passive order. A move is strong when aggression keeps winning. It stalls when passive orders soak it up.</p>`+OFV.aggrPassive()},
  {t:'The bid, the ask and the spread',h:`<p>The <b>bid</b> is the highest price a buyer is waiting to pay. The <b>ask</b> (or offer) is the lowest price a seller is waiting to accept. The gap between them is the <b>spread</b>.</p><ul><li>A <b>market buy</b> pays the ask. It is the aggressive buyer.</li><li>A <b>market sell</b> gets the bid. It is the aggressive seller.</li></ul><p>On NQ the tick is 0.25 points. Each tick is $5 on NQ and $0.50 on MNQ.</p>`},
  {t:'Where orderflow sits beside the strategies',h:`<p>The three strategies in this school all trade a reaction: <b>ECHO</b> trades a sweep that gets rejected, <b>ORBIT</b> trades a pullback into an entry zone, and <b>INVERTIX</b> trades a flip at a key level. In each one, price does something at a level. Orderflow is how you check <b>who</b> did it.</p>`+warn('<p>Orderflow is a second opinion. None of it is a trade on its own, and none of it changes the strategy\'s rules.</p>','Keep this in mind')}],
 recall:rc('Market Basics','What does a market order do?',['It buys or sells right away at the best available price','It waits at a price you choose','It cancels another order','It sets your stop'],'A market order trades now: that is what makes it the aggressive side.'),
 steps:[['<b>Two views of one moment.</b>',tblx(['View','Shows'],[['Candle','Where price went'],['Orderflow','Who pushed it, and how much traded at each price']])],['<b>Aggressive meets passive.</b>',tblx(['Order','Role'],[['Market order','Aggressive: takes the price'],['Resting limit order','Passive: waits']])],['<b>The spread.</b>',`<p>Bid and ask are the two best prices. A market order crosses the spread and pays it. A limit order that waits does not.</p>`]],
 gens:[aggressorQ,ammoQ,spreadQ],
 bank:BANKS('Orderflow basics',[
  ['What does a normal candle show?',['Where price went','Who was aggressive','The size of every order','The news'],'A candle shows the open, high, low and close. Orderflow adds how.'],
  ['What does orderflow add to a candle?',['How price got there: who pushed and how much traded at each price','A forecast','A guaranteed signal','A new time frame'],'It is a second view of the same moment.'],
  ['Which order is aggressive?',['A market order','A limit order resting on the bid','A stop that has not triggered','An order you cancelled'],'Market orders take the price now.'],
  ['Which order is passive?',['A resting limit order','A market buy','A market sell','A triggered stop'],'Limit orders rest and wait.'],
  ['A market buy pays which price?',['The ask','The bid','The close','The open'],'Buyers lift the ask. Sellers hit the bid.'],
  ['A market sell gets which price?',['The bid','The ask','The high','The midpoint'],'Sellers hit the bid.'],
  ['What is the spread?',['The gap between the best bid and the best ask','The range of the day','The size of an order','The commission'],'The spread is the cost of crossing.'],
  ['How much is one tick on MNQ?',['$0.50','$5','$20','$2'],'One tick is 0.25 points: $5 on NQ and $0.50 on MNQ.'],
  ['What makes a move strong in orderflow terms?',['Aggression keeps winning','Passive orders soak up the push','The spread is wide','Volume is low'],'When passive orders soak it up, the move stalls.'],
  ['What is the market, in auction terms?',['Buyers and sellers meeting at a price to find the level both will trade','A place where only market makers trade','A schedule of news','A random walk with no pattern'],'A two-way auction.'],
  ['What is orderflow in this school?',['A second opinion beside the strategies','A strategy on its own','A signal you can trade alone','A way to skip stops'],'It adds context and confirmation, never a trigger.']]),
 examDesc:'What orderflow shows, aggressive and passive orders, the bid, the ask and the spread.'});
/* ---------- f02 · the tape and the DOM ---------- */
quick({id:'f02',o:16.2,ph:0,t:'The Tape and the DOM',out:'Read the time and sales and the depth of market, and know what each can and cannot tell you.',
 ls:['The tape: every trade, as it happens','Volume: how much traded','The DOM: resting orders','Why the DOM can mislead','Icebergs and pulled orders'],
 task:'If your platform has a time and sales window or a DOM, open one on MNQ for a few minutes. Write down what you see: how often trades print, what the usual size is, and how far the best bid and ask are apart.',
 learn:[
  {t:'The tape: every trade, as it happens',h:`<p>The <b>tape</b> (also called <b>time and sales</b>) is a list of every trade: the time, the price, the size, and which side it traded on. A trade at the <b>ask</b> means a buyer was aggressive. A trade at the <b>bid</b> means a seller was aggressive.</p>`+key('<p>The tape is what actually happened. It cannot be faked after the fact.</p>')+OFV.tape()},
  {t:'Volume: how much traded',h:`<p><b>Volume</b> is the number of contracts that traded. A big print is only big compared with the normal size of the moment, so judge size against what is usual for that time of day. Volume tells you how much business was done. It does not say by itself who won.</p>`},
  {t:'The DOM: resting orders',h:`<p>The <b>DOM</b> (depth of market, or the ladder) lists the prices with the <b>resting limit orders</b> at each one: buyers below the market on the bid side, sellers above it on the ask side. It shows who is <b>waiting</b>, not who traded.</p>`+tblx(['Tape','DOM'],[['What traded','What is waiting to trade'],['Real, already happened','Can change in a split second']])+OFV.dom()},
  {t:'Why the DOM can mislead',h:`<p>Any resting order can be <b>cancelled</b> before price reaches it. A large order on the DOM may be real support or resistance, or it may vanish as price gets close. Some traders place orders they never intend to fill. So the DOM is a clue, and it counts only when trades actually happen into it.</p>`},
  {t:'Icebergs and pulled orders',h:`<p>An <b>iceberg</b> is a large order shown in small pieces: only a slice is visible, and it refills as it is hit. You spot one when a level keeps absorbing trades without the visible size shrinking. A <b>pulled order</b> is the opposite: a big order on the DOM that disappears as price approaches.</p>`+warn('<p>Never take a trade because of what you see on the DOM alone. What traded is real, what is waiting can vanish.</p>')}],
 recall:rc('Orderflow: What Orderflow Is','Which order is the aggressive one?',['A market order','A resting limit order','A cancelled order','An order for later'],'Aggressive orders take the price now.'),
 steps:[['<b>Tape or DOM?</b>',tblx(['Question','Look at'],[['What just traded, and on which side?','The tape'],['Where are orders waiting?','The DOM']])],['<b>A market buy meets resting sellers.</b>',`<p>If 60 contracts rest on the ask and a buyer sends a market order for 25, 25 trade (a print at the ask) and 35 are left. That is one aggressive order meeting passive ones.</p>`],['<b>The DOM is a clue.</b>',`<p>A big order that stays while price trades into it and does not vanish is a stronger clue than one that disappears.</p>`]],
 gens:[ammoQ,printQ,domQ],
 bank:BANKS('The tape and the DOM',[
  ['What does the tape (time and sales) show?',['Every trade: time, price, size and side','Orders that are waiting','The news','Your open trades'],'The tape is what actually traded.'],
  ['A trade prints at the ask. Who was aggressive?',['The buyer','The seller','Nobody','The exchange'],'Buyers lift the ask.'],
  ['A trade prints at the bid. Who was aggressive?',['The seller','The buyer','Nobody','The exchange'],'Sellers hit the bid.'],
  ['What does the DOM show?',['Resting limit orders at each price','Every trade that happened','Your account','The news'],'It shows who is waiting.'],
  ['Which is real, what traded or what is on the DOM?',['What traded: it already happened','What is on the DOM','Both are always real','Neither'],'Resting orders can be cancelled.'],
  ['What is an iceberg order?',['A large order shown in small pieces','A stop order','A market order','A cancelled order'],'It refills as it is hit.'],
  ['A big resting order vanishes as price gets close. What is it called?',['A pulled order','An iceberg','A stop run','A gap'],'Resting orders can be pulled at any time.'],
  ['A print is large. What do you do?',['Judge it against the normal size and treat it as context','Follow it at once','Fade it at once','Ignore all volume'],'Size alone does not say direction.'],
  ['Should you trade off the DOM alone?',['No: it is only a clue','Yes, always','Yes, on news','Yes, if it is big'],'Only what actually trades counts.'],
  ['Which tells you which side was aggressive?',['The side a trade printed on, bid or ask','The colour of the candle','The time of day','The spread'],'Bid prints are sellers. Ask prints are buyers.'],
  ['Volume tells you…',['How much business was done, not who won','Who won','Where price goes next','The stop to use'],'It needs the side and the price to mean more.']]),
 examDesc:'The tape, volume, the DOM, and why resting orders can mislead.'});
/* ---------- f03 · the footprint ---------- */
quick({id:'f03',o:16.3,ph:0,t:'The Footprint Chart',out:'Read a footprint candle: the bid and ask volume at every price, and the totals.',
 ls:['A candle with the inside showing','Reading one row','Totals under the candle','What stands out','Getting a footprint on your chart'],
 task:'If you can, open a footprint (or volumetric) chart on MNQ or NQ. Find one candle and say, for its highest and lowest price, which side traded more. If you cannot get one yet, sketch a candle with three price rows and make up the bid and ask volumes.',
 learn:[
  {t:'A candle with the inside showing',h:`<p>A <b>footprint chart</b> splits each candle into <b>price rows</b>. For every price it shows how many contracts traded at the <b>bid</b> (sellers, aggressive) and how many at the <b>ask</b> (buyers, aggressive). It is the same candle you know, with the inside visible.</p>`+OFV.ladder()},
  {t:'Reading one row',h:`<p>Each row answers one question: <b>at this price, who was more aggressive?</b> If the right number is much bigger than the left, buyers pushed there. If the left is bigger, sellers did. Rows where both are large mean heavy two-sided business. Rows where both are small are prices price passed through quickly.</p>`},
  {t:'Totals under the candle',h:tblx(['Number','What it is'],[['Volume','Every contract that traded in the candle (both sides added)'],['Delta','Buyers at the ask minus sellers at the bid'],['Max delta / min delta','The highest and lowest the running delta reached inside the candle']])+`<p>Delta is the one number most traders read first. A candle can close up with negative delta, which is a disagreement worth noticing.</p>`},
  {t:'What stands out',h:`<ul><li><b>Large cells</b> where a lot traded at one price.</li><li><b>Imbalances</b>: one side far bigger than the other (next modules).</li><li><b>Empty rows</b> at the end of a wick: price touched there and nobody traded, a sign it moved fast.</li></ul>`},
  {t:'Getting a footprint on your chart',h:`<p>Many charting platforms offer footprint or volumetric bars: TradingView (on paid plans), NinjaTrader, Sierra Chart, ATAS and others. Futures data is the cleanest source because every trade on the exchange is recorded. Cell size and colours differ between platforms, but the idea is the same.</p>`+warn('<p>Use the same row size and settings every day, so what you see is comparable from day to day.</p>','Practical tip')}],
 recall:rc('Orderflow: The Tape and the DOM','Which shows what actually traded?',['The tape','The DOM','Your stop','A resting order'],'The tape is the record of real trades.'),
 steps:[['<b>One candle, opened up.</b>',OFV.ladder()],['<b>Add it up.</b>',`<p>Sellers: 31 + 44 + 52 + 67 = <b>194</b>. Buyers: 58 + 62 + 41 + 23 = <b>184</b>. Volume = 378. Delta = 184 − 194 = <b>−10</b>. Nearly even.</p>`],['<b>Read the rows.</b>',`<p>The top rows lean to buyers, the bottom rows lean to sellers. That is a candle where buyers won the high prices and sellers won the low ones.</p>`]],
 gens:[deltaCalc,totalVol,deltaCalc],
 bank:BANKS('The footprint',[
  ['What does a footprint chart show that a normal candle does not?',['Bid and ask volume at every price inside the candle','The news','The next candle','The spread of the day'],'It is a candle with the inside visible.'],
  ['In a footprint, the number on the ask side is…',['Buyers who lifted the ask','Sellers who hit the bid','Resting orders','The close'],'Ask prints are aggressive buyers.'],
  ['In a footprint, the number on the bid side is…',['Sellers who hit the bid','Buyers who lifted the ask','Resting orders','The open'],'Bid prints are aggressive sellers.'],
  ['What is delta?',['Buyers at the ask minus sellers at the bid','Volume','The range of the candle','The spread'],'A positive delta means buyers were more aggressive.'],
  ['What is volume in a footprint candle?',['Every contract traded, both sides added','Buyers minus sellers','The biggest cell','The close'],'Volume adds both sides.'],
  ['A candle closes up but its delta is negative. What is it?',['A disagreement worth noticing','A very strong candle','A data error','A news candle'],'Price and aggression did not agree.'],
  ['Where both numbers in a row are small, what happened?',['Price moved through that price quickly','A heavy battle','An iceberg','A pulled order'],'Little trading there.'],
  ['Why use the same row size every day?',['So what you see is comparable day to day','The exchange requires it','It changes the volume','It is a rule of NQ'],'Consistency makes the picture comparable.'],
  ['Why is futures data the cleanest for footprints?',['Every trade on the exchange is recorded','It is free','It has no spread','It never gaps'],'Futures trade on one exchange.'],
  ['Max delta and min delta show…',['The highest and lowest the running delta reached inside the candle','The close and the open','The high and the low','Nothing'],'They show how far each side pushed inside the candle.'],
  ['What does a large cell mean?',['A lot traded at that one price','Price will reverse','A pulled order','A gap'],'It is a place of heavy business.']]),
 examDesc:'Reading a footprint candle: rows, totals, volume and delta.'});
/* ---------- f04 · delta ---------- */
quick({id:'f04',o:16.4,ph:0,t:'Delta and Cumulative Delta',out:'Work out delta and cumulative delta, and read a divergence as a condition, never a trigger.',
 ls:['Delta','Cumulative delta','Delta divergence','What delta cannot tell you','How the strategies use it'],
 task:'Take any five candles from a footprint chart (or invent five delta numbers). Write each candle\'s delta, then the cumulative delta after each one. Say in one line whether buyers or sellers were winning over the five.',
 learn:[
  {t:'Delta',h:def('<p><b>Delta</b> = volume traded at the ask − volume traded at the bid. Positive: buyers were more aggressive. Negative: sellers were.</p>')+`<p>A candle with delta of +180 had 180 more contracts bought aggressively than sold aggressively. The size matters less than the pattern across candles.</p>`},
  {t:'Cumulative delta',h:`<p><b>Cumulative delta (CD)</b> is the running total of delta. Start from zero (for the session, or the day) and add each candle\'s delta.</p>`+tblx(['Candle','Delta','Cumulative'],[['1','+120','+120'],['2','−60','+60'],['3','+90','+150'],['4','−200','−50']])+`<p>A rising line means buyers have been more aggressive overall. A falling line means sellers have.</p>`+OFV.delta()},
  {t:'Delta divergence',h:`<p>A <b>divergence</b> is when price and delta disagree. Price makes a higher high but cumulative delta makes a lower high: the new high had <b>less aggression</b> behind it. The reverse is true for lows.</p>`+warn('<p>Divergences can repeat many times while a trend keeps running. It is a <b>condition to watch</b>, not a trigger. It means look closer, not enter.</p>')+OFV.divergence()},
  {t:'What delta cannot tell you',h:`<ul><li>Delta does not say <b>who is trapped</b> or <b>what happens next</b>.</li><li>It is only the difference of two numbers: a +100 can come from 500 vs 400 or from 150 vs 50. Look at the volume too.</li><li>It depends on the data and the settings of the chart, so compare like with like.</li></ul>`},
  {t:'How the strategies use it',h:`<p>You will not trade delta. You will use it as a <b>check</b> beside a strategy\'s signal. For example, a sweep that is rejected looks better when delta flips against the sweep as price comes back, and worse when the aggression keeps going the same way.</p>`}],
 recall:rc('Orderflow: The Footprint Chart','What is volume in a footprint candle?',['Every contract traded, both sides added','Buyers minus sellers','The biggest cell','The close'],'Volume adds both sides. Delta is the difference.'),
 steps:[['<b>Delta of one candle.</b>',fp([[21452,31,58],[21451,44,62],[21450,52,41]])+`<p>Sellers 127, buyers 161. Delta = 161 − 127 = <b>+34</b>.</p>`],['<b>Running total.</b>',tblx(['Candle','Delta','Cumulative'],[['1','+34','+34'],['2','−80','−46'],['3','+55','+9']])],['<b>A divergence.</b>',`<p>Price: higher high. Cumulative delta: lower high. The push up had less behind it. Watch, do not enter.</p>`]],
 gens:[deltaCalc,cumDelta,divQ],
 bank:BANKS('Delta',[
  ['Delta equals…',['Volume at the ask minus volume at the bid','Volume at the bid minus the ask','Total volume','The range'],'Buyers minus sellers.'],
  ['What does a negative delta mean?',['Sellers were more aggressive','Buyers were more aggressive','Price must fall next','The data is wrong'],'More traded at the bid.'],
  ['What is cumulative delta?',['The running total of delta','The biggest delta of the day','Volume','The spread'],'Add each candle\'s delta.'],
  ['A rising cumulative delta line means…',['Buyers have been more aggressive overall','Sellers have won','Price must rise next','The market is closed'],'It describes what happened, not what comes next.'],
  ['Price makes a higher high and cumulative delta a lower high. What is that?',['Bearish delta divergence','Bullish delta divergence','A buy signal','Nothing'],'Price and aggression disagree.'],
  ['Price makes a lower low and cumulative delta a higher low. What is that?',['Bullish delta divergence','Bearish delta divergence','A sell signal','A gap'],'Less selling behind the new low.'],
  ['Is a divergence a trade signal?',['No: it is a condition to watch','Yes, always','Yes on news days','Yes in the morning'],'Divergences can repeat while a trend runs.'],
  ['Why look at volume as well as delta?',['The same delta can come from very different volumes','Delta is always wrong','Volume is the signal','It is required by the exchange'],'A +100 from 500 vs 400 is not the same as 150 vs 50.'],
  ['Can delta tell you what happens next?',['No','Yes always','Yes on NQ','Yes at the open'],'It describes what already traded.'],
  ['How do you use delta with a strategy?',['As a check beside the signal','As the signal','To replace the stop','To size up'],'A second opinion, never a trigger.'],
  ['Where does cumulative delta usually start?',['At zero for the session or the day','At the previous close','At the high','At the open price'],'Start from zero and add.']]),
 examDesc:'Delta, cumulative delta, and divergence as a condition, never a trigger.'});
/* ---------- f05 · imbalances ---------- */
quick({id:'f05',o:16.5,ph:0,t:'Imbalances and Stacks',out:'Find a buy or sell imbalance with the diagonal test, and read a stack of three or more.',
 ls:['What an imbalance is','The diagonal test','Stacked imbalances','Support and resistance from stacks','What they do not mean'],
 task:'On a footprint chart (or an invented ladder of five rows), find one row where the ask is at least three times the bid one row below it. Mark it. Then find any stack of three in a row, if one exists.',
 learn:[
  {t:'What an imbalance is',h:`<p>An <b>imbalance</b> is a price where one side was far more aggressive than the other. It shows where buyers or sellers pushed hard and the other side barely answered.</p>`},
  {t:'The diagonal test',h:def('<p><b>Buy imbalance:</b> the volume at the <b>ask</b> at one price is at least <b>3 times</b> the volume at the <b>bid</b> one row <b>below</b>. <b>Sell imbalance:</b> the volume at the bid is at least 3 times the volume at the ask one row <b>above</b>.</p>')+`<p>Why diagonal? The ask at one price and the bid at the price right below it are the two sides of the same moment of the auction. Comparing them tells you who won the exchange. The ratio (3 × or 300%) is a common setting. Some traders use different ratios, so keep yours fixed.</p>`+OFV.imbalance()},
  {t:'Stacked imbalances',h:`<p>A <b>stack</b> is <b>three or more</b> imbalances at neighbouring prices in the same direction. One imbalance is noise. A stack says one side was aggressive across a whole range of prices in a row.</p>`+OFV.stack()},
  {t:'Support and resistance from stacks',h:`<p>A stack of <b>buy</b> imbalances on the way up can mark where buyers were strong. If price comes back to that zone later, it can act as <b>support</b>. A stack of sell imbalances can act as <b>resistance</b>. It is a place to watch, not a guarantee that price will react.</p>`},
  {t:'What they do not mean',h:`<ul><li>A stack often shows <b>continuation</b>, because aggressive buyers or sellers are in control. Do not fade a stack just because it looks stretched.</li><li>One imbalance on its own does not mean anything.</li><li>Settings differ between platforms (ratio, minimum volume). Check yours.</li></ul>`}],
 recall:rc('Orderflow: Delta and Cumulative Delta','What is cumulative delta?',['The running total of delta','The biggest delta of the day','Volume','The spread'],'Add each candle\'s delta.'),
 steps:[['<b>The diagonal test.</b>',fp([[21454,20,28],[21453,18,66],[21452,22,31],[21451,24,29]],{a:[1]})+`<p>The ask at 21,453 is 66. The bid one row below, at 21,452, is 22. 66 ≥ 3 × 22 = 66. That is a buy imbalance.</p>`],['<b>A stack.</b>',`<p>Three buy imbalances at neighbouring rows in a row make a stack. It tells you buyers were aggressive across several prices.</p>`],['<b>How to read it.</b>',`<p>A stack is often continuation. As a zone, it can be a place buyers or sellers return to. It never triggers a trade by itself.</p>`]],
 gens:[diagImb,stackCount,stackRole],
 bank:BANKS('Imbalances',[
  ['What is an imbalance?',['A price where one side was far more aggressive','A gap','The spread','A news release'],'One side overwhelmed the other.'],
  ['The common ratio for an imbalance is…',['3 to 1 (300%)','1 to 1','2 to 1 only','10 to 1 only'],'Many platforms use 3 × as the default.'],
  ['A buy imbalance compares…',['The ask at one price with the bid one row below','The bid with the bid','The open with the close','Volume with price'],'It is a diagonal comparison.'],
  ['A sell imbalance compares…',['The bid at one price with the ask one row above','The ask with the ask','The high with the low','Time with price'],'The mirror of a buy imbalance.'],
  ['How many imbalances in a row make a stack?',['Three or more','Two','Five only','One'],'Three or more in the same direction.'],
  ['What does a stack of buy imbalances tell you?',['Buyers were aggressive across several prices','Price must fall','The spread widened','Nothing'],'Aggression across a range.'],
  ['A stack of buy imbalances breaks up out of a range. What is the usual read?',['Often continuation','Always a reversal','A sell signal','A gap'],'Do not fade it without more.'],
  ['Can a stack act as support or resistance?',['Yes, as a zone to watch, not a guarantee','Yes, always','No, never','Only on the daily chart'],'Price may or may not react there.'],
  ['Is a single imbalance cell a strong signal?',['No: it is noise on its own','Yes','Yes on news days','Yes at the open'],'Stacks carry more weight.'],
  ['Why keep your ratio setting fixed?',['So you read every day the same way','The exchange sets it','It changes the volume','It changes the spread'],'Settings change what is flagged.'],
  ['Should you fade a stack just because it looks stretched?',['No','Yes','Yes at the high','Yes at the open'],'Stacks often continue.']]),
 examDesc:'The diagonal test, stacked imbalances, and how to read them.'});
/* ---------- f06 · absorption, exhaustion, trapped ---------- */
quick({id:'f06',o:16.6,ph:0,t:'Absorption, Exhaustion and Trapped Traders',out:'Recognise absorption, exhaustion and trapped traders, and know they are clues rather than signals.',
 ls:['Absorption','Exhaustion','Trapped traders','Putting them in order','What they are not'],
 task:'Find a candle on any chart with a long wick into a level. Write whether the story could be absorption (heavy trading, no progress), exhaustion (the push faded) or trapped traders (a failed break). Write what you would need to see on a footprint to be more sure.',
 learn:[
  {t:'Absorption',h:def('<p><b>Absorption</b> is heavy aggressive trading at a price that makes <b>little progress</b>. A big passive order is soaking up the aggressors.</p>')+`<p>Picture buyers hitting the ask again and again at a high, and price will not rise. Somebody with a large resting sell order is filling them. When the buyers run out, that passive seller has won the exchange.</p>`+OFV.absorption()},
  {t:'Exhaustion',h:def('<p><b>Exhaustion</b> is a push that <b>runs out of fuel</b>: each new high comes with less delta and less volume than the one before.</p>')+`<p>The buyers are not being soaked up: they simply stop coming. Price stalls or turns because nobody is left to push.</p>`+OFV.exhaustion()},
  {t:'Trapped traders',h:`<p>Traders who enter on a break are <b>trapped</b> if the break fails and price falls back through their entry. They are now losing, and their stops (which are market orders when triggered) add to the move against them.</p><p>This is why a failed break can reverse faster than a normal move.</p>`+OFV.trapped()},
  {t:'Putting them in order',h:tblx(['Clue','What it looks like','The question it asks'],[['Absorption','Big volume at a level, price stuck','Who is on the other side?'],['Exhaustion','Delta and volume fade on each push','Is anyone left to push?'],['Trapped traders','A break fails and price snaps back','Who has to get out now?']])},
  {t:'What they are not',h:warn('<p>None of these is a signal on its own. You can only judge them <b>after</b> the fact, and it is easy to see absorption everywhere once you are looking for it. They are clues that fit a story: a sweep that gets rejected, a level that holds, a flip that follows through.</p>','Be careful')}],
 recall:rc('Orderflow: Imbalances and Stacks','How many imbalances in a row make a stack?',['Three or more','Two','Five only','One'],'Three or more in the same direction.'),
 steps:[['<b>Absorption.</b>',tblx(['Sees','Meaning'],[['Heavy buying at a high','Aggressive buyers'],['Price will not rise','A passive seller soaks them up']])],['<b>Exhaustion.</b>',tblx(['Push','Delta'],[['1st high','+260'],['2nd high','+150'],['3rd high','+60']])+`<p>Each push has less behind it.</p>`],['<b>Trapped traders.</b>',`<p>Price breaks above a level, buyers pile in, price falls back under the level. Everyone who bought the break is now wrong.</p>`]],
 gens:[absorbQ,sortAbs,divQ],
 bank:BANKS('Absorption and exhaustion',[
  ['What is absorption?',['Heavy aggressive trading with little progress','A gap','A news spike','A stop order'],'A passive order soaks up the aggression.'],
  ['What is exhaustion?',['A push that runs out of fuel','A big candle','A gap fill','A stop run'],'Each push has less behind it.'],
  ['What are trapped traders?',['Late entries forced out when a break fails','The market makers','Scalpers only','Traders with stops'],'Their stops add to the move.'],
  ['Heavy buying hits the ask and price does not rise. What is it?',['Absorption','Exhaustion','A breakout','A gap'],'A big passive seller is soaking it up.'],
  ['Each new high comes with less delta. What is it?',['Exhaustion','Absorption','A reversal that has happened','A gap'],'The push is losing fuel.'],
  ['A break fails and price snaps back through the level. Who is hurt?',['The traders who entered on the break','The sellers','Nobody','The exchange'],'Trapped traders have to get out.'],
  ['Can you trade absorption on its own?',['No: it is a clue, not a signal','Yes','Yes at the open','Yes on news'],'It is easy to see everywhere once you look for it.'],
  ['Why is a failed break fast?',['Trapped traders exiting add to the move','The exchange speeds it up','Volume is low','It is random'],'Their stops are market orders.'],
  ['How do you judge absorption?',['By heavy volume at a level with little price progress','By the candle colour','By the time of day','By the news'],'Lots of trading, little movement.'],
  ['A candle closes up but delta is negative. What do you do?',['Notice the disagreement and look closer','Buy at once','Sell at once','Ignore it'],'It is a clue, not a signal.'],
  ['What question does absorption ask?',['Who is on the other side?','Is anyone left to push?','Who has to get out?','Where is the news?'],'That is the question that separates it from exhaustion.']]),
 examDesc:'Absorption, exhaustion and trapped traders, and why they are clues and not signals.'});
/* ---------- f07 · auction theory ---------- */
quick({id:'f07',o:16.7,ph:0,t:'Auction Theory, Value and the Volume Profile',out:'Read value, the point of control, balance and imbalance, and initiative versus responsive activity.',
 ls:['The market looks for fair value','The volume profile and the point of control','Watching a profile build','Value area','Profile shapes','High and low volume nodes','Balance and imbalance','Initiative and responsive','Where the day opens against yesterday\'s value','The point of control moves','Finished and unfinished auctions'],
 task:'Open a volume profile (session or visible range) on MNQ for yesterday. Mark the point of control and the top and bottom of the value area. Write whether today opened inside or outside yesterday\'s value, and what that suggests.',
 learn:[
  {t:'The market looks for fair value',h:`<p>In <b>auction market theory</b>, price moves to find where both buyers and sellers are happy to trade. Where lots of business is done, that price is accepted as <b>fair</b>. Where little business is done, price moves through quickly.</p>`},
  {t:'The volume profile and the point of control',h:`<p>A <b>volume profile</b> turns the chart on its side: for each price, a bar shows how many contracts traded there over a period. The longest bar is the <b>point of control (POC)</b>: where the most business was done.</p>`+OFV.profile()},
  {t:'Watching a profile build',h:`<p>A profile is not drawn in one go: it <b>builds</b> as the day goes on. Every time price trades at a level, that level\'s bar gets longer. Prices where price lingers become long bars. Prices price only passed through stay short.</p>`+OFV.build()+`<p>This is why the profile tells you where the market <b>accepted</b> price (long bars) and where it only <b>passed through</b> (short bars).</p>`},
  {t:'Value area',h:`<p>The <b>value area</b> is the range around the POC that holds about <b>70%</b> of the volume. Its top is the <b>value area high (VAH)</b> and its bottom the <b>value area low (VAL)</b>. Price inside the value area is in fair territory. Price outside it is somewhere the market has not yet accepted.</p>`},
  {t:'Profile shapes',h:`<p>The overall shape of a day\'s profile often says what kind of day it was. These are descriptions of what already happened, not forecasts.</p>`+OFV.shapes()},
  {t:'High and low volume nodes',h:`<p>A <b>high volume node (HVN)</b> is a price with a lot of volume: the market agreed on it, so price tends to slow down or rotate there. A <b>low volume node (LVN)</b> is a price range with little volume: price moved through it quickly because nobody wanted to trade there.</p>`+OFV.nodes()+key('<p>An LVN is the profile version of a fair value gap. A gap is a range price skipped. An LVN is a range price skipped. Same idea, seen on a different chart.</p>')},
  {t:'Balance and imbalance',h:tblx(['State','What price does'],[['Balance','Rotates around the POC inside the value area: both sides agree for now'],['Imbalance','Leaves value and trends: the market is looking for a new fair price']])+OFV.balance()},
  {t:'Initiative and responsive',h:tblx(['Activity','What it is','Where it happens'],[['Initiative','Moves price away from value to find new value','Outside yesterday\'s value area'],['Responsive','Pushes price back toward value','Inside or returning to value']])+`<p>If price moves outside value and <b>holds</b> there with rising volume, the initiative side is winning. If it gets rejected and falls back inside, the responsive side won.</p>`+OFV.initResp()},
  {t:'Where the day opens against yesterday\'s value',h:`<p>The first question of any day: where does it open compared with <b>yesterday\'s value area</b>?</p>`+OFV.openVs()+`<p>Inside value usually means balance: expect rotation toward the POC. Outside value is the interesting case: if price <b>holds</b> outside, initiative is in control. If it falls back inside, the responsive side won.</p>`},
  {t:'The point of control moves',h:`<p>Through the day the POC is not fixed. It develops as volume builds. If it stays in one place, the day is in balance. If it keeps stepping in one direction, <b>value is migrating</b> and one side is in control.</p>`+OFV.migrate()},
  {t:'Finished and unfinished auctions',h:`<p>A high or low is <b>finished</b> when price was rejected hard there: little or no trading above the high, a sharp turn. It is <b>unfinished</b> when price just stopped without a clear rejection, with the same trade volume at the extreme as inside the candle. Unfinished extremes are sometimes revisited. These are ideas to watch, not rules that always hold.</p>`}],
 recall:rc('Orderflow: Absorption, Exhaustion and Trapped Traders','What is absorption?',['Heavy aggressive trading with little progress','A gap','A news spike','A stop order'],'A passive order soaks up the aggression.'),
 steps:[['<b>The profile.</b>',`<p>The longest bar is the POC. About 70% of the volume sits in the value area around it. Price outside value is somewhere the market has not yet accepted.</p>`],['<b>Initiative or responsive?</b>',tblx(['Price does','Activity'],[['Moves away from value and holds','Initiative'],['Falls back into value','Responsive']])],['<b>Balance, then imbalance.</b>',`<p>A day often starts in balance around yesterday\'s POC, then breaks out into imbalance when one side takes control.</p>`]],
 gens:[pocQ,auctionQ,gapQ,shapeQ,nodeQ],eb:5,
 bank:BANKS('Auction theory',[
  ['What is the point of control (POC)?',['The price with the most volume','The highest price','The open','The close'],'Where the most business was done.'],
  ['What does the value area hold?',['About 70% of the volume','All the volume','10% of the volume','The high and low only'],'It is the range around the POC.'],
  ['VAH and VAL stand for…',['Value area high and value area low','Volume at high and low','Very active high and low','Value at hand'],'The top and bottom of the value area.'],
  ['Price rotates around the POC inside the value area. What is that?',['Balance','Imbalance','A breakout','Exhaustion'],'Both sides agree for now.'],
  ['Price leaves value and holds outside with rising volume. What is that?',['Imbalance: looking for new value','Balance','Absorption of everyone','A gap'],'The market is looking for a new fair price.'],
  ['Moving away from value is…',['Initiative activity','Responsive activity','A gap','Balance'],'Initiative looks for new value.'],
  ['Pushing price back toward value is…',['Responsive activity','Initiative activity','A breakout','A news spike'],'Responsive returns toward value.'],
  ['A break above yesterday\'s high is rejected and price falls back inside range. Who won?',['The responsive side','The initiative side','Nobody','The news'],'Buyers failed to find acceptance.'],
  ['What is a finished high?',['Price was rejected hard with little trading above','Price just stopped','The highest volume','A gap'],'A sharp turn at the extreme.'],
  ['Is auction theory a set of rules that always hold?',['No: they are ideas to read context','Yes','Yes on NQ','Yes in the morning'],'Treat them as context.'],
  ['What does a volume profile show?',['Contracts traded at each price over a period','Time at each price','News','Your fills'],'Volume by price.'],
  ['What is a high volume node (HVN)?',['A price with a lot of volume that the market accepted','A gap price skipped through','The day\'s high','A news spike'],'Price tends to slow or rotate there.'],
  ['What is a low volume node (LVN)?',['A price range with little volume that price moved through quickly','The longest bar','The value area high','The open'],'The profile version of a fair value gap.'],
  ['A profile with a fat top and a thin tail below is called a…',['P shape','D shape','b shape','Thin shape'],'Often buyers moved price up and it was then accepted high.'],
  ['A bell-shaped profile around one price usually means…',['A balanced day: price rotated around one fair price','A fast trend day','A gap day','A news day'],'That is the D shape.'],
  ['The POC keeps stepping up through the day. What does that suggest?',['Value is migrating up: buyers are in control','Balance','Nothing','Sellers are in control'],'A moving POC means one side is in control.'],
  ['The day opens inside yesterday\'s value area. What is the usual first expectation?',['Rotation toward the POC: balance','A trend','A gap fill','A reversal'],'Outside value is the case to watch.'],
  ['Why does a profile get its long bars where price lingered?',['Each time price trades at a level that level\'s volume grows','Long bars are drawn by hand','The exchange adds them','They are random'],'It builds as the day goes on.']]),
 examDesc:'The volume profile and how it builds, its shapes, high and low volume nodes, the open against value, and initiative versus responsive activity.'});
/* ---------- f08 · orderflow at sweeps ---------- */
quick({id:'f08',o:16.8,ph:0,t:'Orderflow at Sweeps: Where ECHO and ORBIT Begin',out:'Read a stop run and a rejection in orderflow terms, and know what flow adds to ECHO and ORBIT.',
 ls:['Why price goes to liquidity','What a sweep looks like in the flow','FVGs and rejection blocks, in orderflow terms','Flag, not trigger','Orderflow and an ECHO rejection','Orderflow and an ORBIT entry'],
 task:'Find a sweep of a prior high or low on a 1-minute chart in replay. Write the story in five lines in order: what was resting there, what traded through, what the aggression did next, how it closed, and what the strategy\'s own confirmation was.',
 learn:[
  {t:'Why price goes to liquidity',h:`<p>You have already learned that stops rest above highs and below lows. In orderflow terms those stops are <b>market orders waiting to fire</b>: a buyer\'s stop above a high becomes an aggressive buy when price trades through it. Price is drawn there because that is where the orders to trade against are.</p>`},
  {t:'What a sweep looks like in the flow',h:`<ol><li>Price moves toward the level.</li><li>Price trades through it, and <b>aggressive orders flood in</b> as the stops fire.</li><li>The aggression <b>stops making progress</b>: price cannot hold beyond the level. This is absorption.</li><li>Price <b>closes back inside</b> the level. The sweep is rejected.</li></ol>`+key('<p>The long wick on the candle is the price view. The flood of aggression that went nowhere is the flow view. They are the same event read twice.</p>')+OFV.sweep()},
  {t:'FVGs and rejection blocks, in orderflow terms',h:`<p>You learned two price ideas: the <b>fair value gap (FVG)</b> and the <b>rejection block</b>. Orderflow explains both with one story: <b>aggression wins, then aggression is refused</b>.</p>`+tblx(['','Price view','Orderflow view'],[['Fair value gap','Three candles where the middle one moved so fast the outer two do not overlap','Aggression won: one side overwhelmed the other. In a footprint you see stacked imbalances and thin rows, with little traded inside the range'],['Rejection block','A candle that wicks into a level or a gap and closes back out','Aggression was absorbed: heavy trading in the wick, little progress, then delta flipping. The wick CE (the middle of the wick) marks the middle of the refused range'],['Together','A rejection block that sits inside a fair value gap','Price returns to the skipped range, and the unfinished business there absorbs it. A gap made by strong, one-sided aggression leaves a more meaningful zone to be refused at']])+`<p>This is why ECHO grades a rejection block by the fair value gap it sits in: the gap tells you how strong the original aggression was, and the rejection tells you the aggression has now been refused.</p>`+OFV.fvgRb()+key('<p>FVG = where aggression ran. Rejection block = where aggression was refused. Same chart, two languages.</p>')},
  {t:'Flag, not trigger',h:`<p>A sweep with flow that agrees is a good <b>flag</b>: look closely here. It is not a trigger. The strategy\'s own confirmation still has to appear. A sweep that keeps getting more aggression and holds beyond the level is not a rejection at all.</p>`},
  {t:'Orderflow and an ECHO rejection',h:`<p><b>ECHO</b> trades a sweep that is rejected: a rejection block forms, and price closes back through the CISD line. In flow terms:</p>${tblx(['Supports the setup','Makes you skip'],[['Aggression into the sweep that stalls, then delta flips against the sweep','Sellers or buyers keep winning after the sweep and price holds beyond the level'],['The rejection candle shows heavy trading and little progress at the extreme','The sweep candle closes beyond the level with strong delta']])}<p>The rejection block, the CISD and the ECHO checklist decide the trade. Flow is an extra look.</p>`},
  {t:'Orderflow and an ORBIT entry',h:`<p><b>ORBIT</b> takes a pullback into a 3-minute optimal entry zone with a 5-minute inversion. In flow terms, the pullback into the zone looks best when the aggression behind it is light and fading, and the move away from the zone comes with stronger delta. A heavy, one-sided pullback straight through the zone is a reason to skip. The entry zone, the inversion and the limit entry still decide the trade.</p>`}],
 recall:rc('Orderflow: Orderflow at Gaps and Levels','Is flow at a key level a trigger?',['No: the strategy gives the trigger','Yes','Yes on news days','Yes in the morning'],'Flow adds or removes confidence.'),
 steps:[['<b>The stop run in order.</b>',`<ol><li>Price runs toward resting stops.</li><li>It trades through them: aggression floods in.</li><li>The aggression stalls.</li><li>Price closes back inside.</li></ol>`],['<b>A sweep with flow that agrees.</b>',tblx(['Price','Flow'],[['Wick through the high','Big aggressive buying through the level'],['Close back below','Little progress: absorbed']])],['<b>A sweep that is not rejected.</b>',`<p>Price trades through the high, closes beyond it, and the buying keeps coming. That is not absorption: that is a break, so skip the rejection.</p>`]],
 gens:[sweepOrder,confirmQ,fitQ,fvgRbQ],
 bank:BANKS('Sweeps and flow',[
  ['What are stops, in orderflow terms?',['Market orders waiting to fire','Resting limit orders','Cancelled orders','Gaps'],'A stop becomes an aggressive order once price touches it.'],
  ['What is a sweep?',['Price trading through a level to take the orders resting there','A gap','A news candle','A volume profile'],'It takes the stops.'],
  ['What does absorption look like at a sweep?',['Aggression floods in and makes no progress','Price keeps going','A gap','The candle is empty'],'The aggression goes nowhere.'],
  ['A sweep closes back inside the level. What is that?',['A rejected sweep','A breakout','A gap','A news spike'],'The close shows it.'],
  ['A sweep with agreeing flow is…',['A good flag to look closer, not a trigger','A buy signal','A sell signal','A reason to double size'],'The strategy\'s confirmation is still needed.'],
  ['What decides an ECHO trade?',['The rejection block, the CISD and the checklist','The footprint alone','The delta alone','The news'],'Flow is an extra look.'],
  ['What decides an ORBIT trade?',['The entry zone, the inversion and the limit entry','The footprint alone','The DOM','The news'],'Flow is an extra look.'],
  ['Flow makes you skip an ECHO setup when…',['The aggression keeps winning and price holds beyond the level','Price closes back inside','The wick is long','The spread is small'],'That is not a rejection.'],
  ['The ORBIT pullback is heavy and one-sided against you. What do you do?',['Skip: flow does not back it','Enter anyway','Double size','Remove the stop'],'A reason to skip.'],
  ['The long wick and the flood of aggression that went nowhere are…',['The same event read twice','Two different events','A news release','A gap'],'Price view and flow view.'],
  ['What does the CISD represent in flow terms?',['Aggression changing hands: price closes back through the move\'s open','A volume spike','A gap','A news candle'],'It is the price-based version of the flip in aggression.'],
  ['In orderflow terms, a fair value gap is…',['A range where aggression won and price skipped through','A range with the most volume','A wick with heavy trading','A news candle'],'Stacked imbalances and thin rows.'],
  ['In orderflow terms, a rejection block is…',['A wick where aggression was absorbed and refused','A stack of imbalances','A range price skipped','A gap'],'Heavy trading, little progress, then delta flips.'],
  ['Why does ECHO grade a rejection block by the fair value gap it sits in?',['The gap shows how strong the original aggression was, the block shows it was refused','The gap is always bigger','Gaps replace stops','Blocks have no meaning alone'],'The two ideas describe one story.']]),
 examDesc:'The stop run in flow terms, how fair value gaps and rejection blocks match in orderflow, flag versus trigger, and what flow adds to ECHO and ORBIT.'});
/* ---------- f09 · orderflow at gaps and levels ---------- */
quick({id:'f09',o:16.9,ph:0,t:'Orderflow at Gaps and Levels: Where INVERTIX Begins',out:'Read flow at a fair value gap, a key level and a gamma wall, and know what it adds to INVERTIX.',
 ls:['A gap, seen through the flow','Levels and who defends them','Gamma levels as flow context','Orderflow and an INVERTIX flip','When flow says wait'],
 task:'Find an unfilled fair value gap on a 15-minute chart. Note what the volume did when it formed. Then replay price returning to it and write what the aggression did on the way in and at the level.',
 learn:[
  {t:'A gap, seen through the flow',h:`<p>A <b>fair value gap</b> is a range price skipped through quickly: very little trading happened inside it. On a volume profile the same thing shows up as a <b>low volume node</b>. In flow terms it is a place where <b>one side overwhelmed the other</b> and the other side did not have time to trade. That is why price is often drawn back: there is unfinished business and resting orders around it.</p>`+OFV.fvg()},
  {t:'Levels and who defends them',h:`<p>A <b>key level</b> is a price where orders are likely to react: a higher-timeframe gap, a rejection block, a high or low inside a gap. Flow shows you whether the level is being <b>defended</b> (aggression absorbed) or <b>run over</b> (aggression keeps winning).</p>`+tblx(['At the level you see','It suggests'],[['Heavy trading, little progress','The level is being defended'],['Strong one-sided delta that keeps pushing through','The level may fail']])+OFV.defended()},
  {t:'Gamma levels as flow context',h:`<p>The daily <b>GEX levels</b> (call wall, put wall, gamma flip) mark prices where options positioning may make dealers trade against or with price. They tend to be places where heavy trading shows up. Read the flow when price gets to one: absorption there supports a reaction, and a one-sided run through it says the wall is not holding. It is context, not a promise.</p>`},
  {t:'Orderflow and an INVERTIX flip',h:`<p>INVERTIX waits for a manipulation leg into a key level, then a <b>flip</b>: a strong candle that closes through the highest small gap in the leg. In flow terms:</p>${tblx(['Supports the setup','Makes you skip'],[['The leg into the key level runs out of aggression, and the flip candle comes with strong delta the other way','The flip candle is weak and the leg\'s aggression is still strong'],['The level looks defended: heavy trading, little progress','Price runs through the level with one-sided delta']])}<p>The key level, the flip, the ticket and the stop rules decide the trade.</p>`},
  {t:'When flow says wait',h:`<p>If the flow at a level is huge and one-sided, <b>be patient</b>. You do not have to take the first touch. The strategies are built to wait for their own confirmation, and flow is a good reason to wait for it.</p>`}],
 recall:rc('Orderflow: Auction Theory, Value and the Volume Profile','What is the point of control?',['The price with the most volume','The highest price','The open','The close'],'Where the most business was done.'),
 steps:[['<b>A gap in flow terms.</b>',`<p>Fast move, little trading inside the range, resting orders around it. Price often returns to finish the business.</p>`],['<b>Defended or run over?</b>',tblx(['At the level','Read'],[['Heavy volume, price stuck','Defended'],['One-sided delta, price keeps going','Run over']])],['<b>A flip with flow behind it.</b>',`<p>The leg faded, then the flip candle came with strong delta the other way. Both pieces agree.</p>`]],
 gens:[lvlQ,gapQ,fitQ],
 bank:BANKS('Gaps and levels',[
  ['What is a fair value gap in flow terms?',['A range where one side overwhelmed the other so fast little traded','A range with the most volume','A news candle','The value area'],'A skipped range.'],
  ['Why is price often drawn back to a gap?',['Unfinished business and resting orders around it','A law of the market','The clock','The spread'],'It is a tendency, not a rule.'],
  ['A level is being defended when…',['Heavy trading makes little progress against it','Price runs through it with strong delta','Volume dries up','The spread widens'],'Aggression is absorbed.'],
  ['A level may fail when…',['One-sided aggression keeps winning through it','Price stalls','Volume is heavy and price is stuck','The wick is long'],'Aggression keeps winning.'],
  ['What are GEX levels?',['Options-based levels such as call wall, put wall and gamma flip','Volume levels','News levels','Gap levels'],'They are context for where price may react.'],
  ['Heavy trading and little progress at a gamma wall suggests…',['The wall is being absorbed: a clue for a reaction','A sure bounce','A sure break','Nothing'],'A clue, not a promise.'],
  ['What decides an INVERTIX trade?',['The key level, the flip, the ticket and the stop rules','The footprint alone','The DOM','The news'],'Flow is an extra look.'],
  ['The flip candle is weak and the leg\'s aggression is still strong. What do you do?',['Treat it as a reason to skip','Enter anyway','Double size','Remove the stop'],'Flow does not back it.'],
  ['The flow at a level is huge and one-sided. What do you do?',['Be patient and wait for the strategy\'s signal','Take the first touch','Double size','Skip your stop'],'You do not have to take the first touch.'],
  ['A strong flip candle comes after a leg that ran out of aggression. What is that?',['Flow supporting the setup','Flow against the setup','Nothing','A news spike'],'Both pieces agree.'],
  ['Is flow at a key level a trigger?',['No: the strategy gives the trigger','Yes','Yes on news days','Yes in the morning'],'Flow adds or removes confidence.']]),
 examDesc:'Flow at a gap, a key level and a gamma wall, and what flow adds to INVERTIX.'});
/* ---------- f10 · putting flow on the strategies ---------- */
quick({id:'f10',o:17,ph:0,t:'Putting Flow Beside the Strategies',out:'Use orderflow as a second opinion beside ECHO, ORBIT and INVERTIX, and know what it never overrides.',
 ls:['One rule for all three strategies','What supports a setup','What makes you skip','What flow never overrides','Keeping a flow log','What comes next'],
 task:'Write your own one-page flow checklist for the strategies: three things that support a setup, three that make you skip, and the four things flow never overrides. Keep it next to your chart.',
 learn:[
  {t:'One rule for all three strategies',h:key('<p><b>The strategy gives the trigger. Orderflow is a second opinion.</b> It can add confidence or tell you to skip. It never replaces the strategy\'s rules.</p>')+OFV.strategies()},
  {t:'What supports a setup',h:`<ul><li>Aggression into the level that <b>stalls</b> (absorption).</li><li>A push that is <b>fading</b>: smaller delta each time.</li><li>Delta <b>flipping</b> the other way as price comes back.</li><li>Trapped traders on the wrong side.</li></ul>`},
  {t:'What makes you skip',h:`<ul><li>Aggression that <b>keeps winning</b> and price holds beyond the level.</li><li>A signal candle with <b>weak or opposite</b> delta.</li><li>A heavy, one-sided move straight through your entry zone.</li><li>Flow that clearly disagrees with the signal.</li></ul>`+warn('<p>If the flow is just unclear, that is not a reason to break your rules. The strategy still decides. Unclear flow is just "no extra confidence".</p>')},
  {t:'What flow never overrides',h:tblx(['Never overridden by flow','Why'],[['Your stop','The stop is where the rules put it'],['The strategy\'s windows','A great footprint outside the window is outside the window'],['Your size and daily loss limit','Flow cannot make a bigger size safe'],['The strategy\'s own signal','No signal, no trade']])},
  {t:'Keeping a flow log',h:`<p>For every trade, note one line on the flow: what it showed, and whether you took the trade because of it, in spite of it, or without it. After fifty trades, compare. Do not decide from three. You are building your own evidence, and nothing in this course claims results.</p>`},
  {t:'What comes next',h:`<p>You have finished the orderflow course. All three strategies are now open: <b>INVERTIX</b> has its own page, and <b>ECHO and ORBIT</b> are in the vault for mentorship members. Each lesson there will point back to the flow ideas you learned here.</p>`}],
 recall:rc('Orderflow: Orderflow at Sweeps','What does absorption look like at a sweep?',['Aggression floods in and makes no progress','Price keeps going','A gap','The candle is empty'],'The aggression goes nowhere.'),
 steps:[['<b>The one rule.</b>',`<p>The strategy gives the trigger. Flow is a second opinion.</p>`],['<b>Supports or skip?</b>',tblx(['You see','Do'],[['Aggression stalls at the sweep, then delta flips','Supports the setup'],['Aggression keeps winning beyond the level','Skip'],['Flow is unclear','The strategy still decides']])],['<b>The never list.</b>',`<p>Stop, windows, size and daily limit, and the strategy\'s own signal: flow never overrides them.</p>`]],
 gens:[confirmQ,neverQ,fitQ,sweepOrder],
 bank:BANKS('Flow beside the strategies',[
  ['Who gives the trigger?',['The strategy','The footprint','The DOM','The news'],'Flow is a second opinion.'],
  ['What can flow do?',['Add confidence or tell you to skip','Give a trigger','Move your stop','Change your size'],'It never replaces the rules.'],
  ['Which supports an ECHO setup?',['Aggression into the sweep that stalls, then delta flips against it','Aggression that keeps winning past the level','A weak signal candle','A heavy one-sided move through the zone'],'The first fits a rejected sweep.'],
  ['Which makes you skip?',['Aggression keeps winning and price holds beyond the level','Absorption at the extreme','Fading delta on a push','Trapped traders on the wrong side'],'That is not a rejection.'],
  ['The flow is unclear. What do you do?',['The strategy still decides: no extra confidence','Skip every trade','Double size','Move the stop'],'Unclear is not a reason to break rules.'],
  ['Can flow override your stop?',['No','Yes if flow looks strong','Yes on the first trade','Yes if you are late'],'The stop is where the rules put it.'],
  ['Can flow override the strategy\'s windows?',['No','Yes','Yes on news days','Yes at the open'],'Outside the window is outside the window.'],
  ['Can flow make a bigger size safe?',['No','Yes','Yes with absorption','Yes on NQ'],'Size and the daily limit are never overridden.'],
  ['What do you note in a flow log?',['What the flow showed and whether you traded because of it, in spite of it or without it','Only the profit','Only the news','Nothing'],'Build your own evidence.'],
  ['When do you judge whether flow helps?',['After many trades, such as fifty','After one trade','After three','Never'],'Do not decide from a few.'],
  ['After this course, what opens?',['INVERTIX, and ECHO and ORBIT for mentorship members','Nothing','Only INVERTIX','Only ECHO'],'All three strategies open once every module is passed.']]),
 examDesc:'Flow as a second opinion beside all three strategies, and what it never overrides.'});
})();
